class Solution {
    public int nextGreaterElement(int n){
        char[] digits=String.valueOf(n).toCharArray();
        int pivot=digits.length-2;
        while(pivot>=0&&digits[pivot]>=digits[pivot+1])pivot--;
        if(pivot<0)return -1;
        int successor=digits.length-1;
        while(digits[successor]<=digits[pivot])successor--;
        char value=digits[pivot];
        digits[pivot]=digits[successor];
        digits[successor]=value;
        for(int left=pivot+1,right=digits.length-1;left<right;left++,right--){
            value=digits[left];
            digits[left]=digits[right];
            digits[right]=value;
        }
        long answer=Long.parseLong(new String(digits));
        return answer>Integer.MAX_VALUE?-1:(int)answer;
    }
}

